                byte[] payload = canonicalize(frames);
                byte[] canonical = canonicalEnvelope(envelope, pn, expected, payload);
                shaOut = AuditIo.hex(AuditIo.sha256().digest(canonical));
                level.seen.add(pn);
                if (pn > level.largest) {
                    level.largest = pn;
                }
                if (envelope.level == LEVEL_A) {
                    recordEpoch(claimed, pn);
                }
                if (close == null) {
                    status = OK;
                } else {
                    closeConnection(close[0], close[1], event, packetIndex);
                    status = PEER_CLOSE;
                }
            } catch (Fail failure) {
                journal.undoAll();
                status = failure.status;
                if (KEY_UPDATE_ERROR.equals(status)) {
                    closeConnection(ERROR_KEY_UPDATE, 0, event, packetIndex);
                }
            }
            journal.commit();
            if (shaOut != null) {
                accepted++;
                bytes += canonicalLength;
                datagramDigest.update(canonicalBytes);
            }
            packets.add(
                    Main.object(
                            "event",
                            event,
                            "packet",
                            packetIndex,
                            "offset",
                            headerOffset,
                            "level",
                            LEVEL_NAMES[envelope.level],
                            "pn",
                            pn,
                            "epoch",
                            epochOut,
                            "status",
                            status,
                            "sha256",
                            shaOut));
            position = envelope.envelopeEnd;
        }
        datagrams.add(
                Main.object(
                        "event",
                        event,
                        "packets",
                        reached,
                        "accepted",
                        accepted,
                        "bytes",
                        bytes,
                        "sha256",
                        AuditIo.hex(datagramDigest.digest())));
    }

    // ------------------------------------------------------------------ header framing

    /** Parses one envelope header, or returns null when the header is malformed. */
    private Envelope parseHeader(byte[] wire, int position) {
        try {
            int first = wire[position] & 255;
            if ((first & 0x80) != 0) {
                if (position + 5 > wire.length) {
                    return null;
                }
                long version =
                        ((wire[position + 1] & 255L) << 24)
                                | ((wire[position + 2] & 255L) << 16)
                                | ((wire[position + 3] & 255L) << 8)
                                | (wire[position + 4] & 255L);
                if (version != 1) {
                    return null;
                }
                int typeBits = (first >>> 4) & 3;
                int level = typeBits == 0 ? LEVEL_I : typeBits == 2 ? LEVEL_H : -1;
                if (level < 0 || (first & 0x30) != 0) {
                    return null;
                }
                int width = (first & 3) + 1;
                int cursor = position + 5;
                if (cursor >= wire.length) {
                    return null;
                }
                int destinationLength = wire[cursor++] & 255;
                if (destinationLength > 20 || cursor + destinationLength > wire.length) {
                    return null;
                }
                byte[] destination = Arrays.copyOfRange(wire, cursor, cursor + destinationLength);
                cursor += destinationLength;
                if (cursor >= wire.length) {
                    return null;
                }
                int sourceLength = wire[cursor++] & 255;
                if (sourceLength > 20 || cursor + sourceLength > wire.length) {
                    return null;
                }
                byte[] source = Arrays.copyOfRange(wire, cursor, cursor + sourceLength);
                cursor += sourceLength;
                byte[] token = new byte[0];
                if (level == LEVEL_I) {
                    int[] hold = {cursor};
                    long tokenLength = readVarint(wire, hold, wire.length);
                    cursor = hold[0];
                    if (tokenLength > wire.length - cursor) {
                        return null;
                    }
                    token = Arrays.copyOfRange(wire, cursor, cursor + (int) tokenLength);
                    cursor += (int) tokenLength;
                }
                int[] hold = {cursor};
                long length = readVarint(wire, hold, wire.length);
                cursor = hold[0];
                if (length < width || cursor + length > wire.length) {
                    return null;
                }
                Envelope envelope = new Envelope();
                envelope.level = level;
                envelope.destination = destination;
                envelope.source = source;
                envelope.token = token;
                envelope.numberWidth = width;
                envelope.numberRaw = readNumber(wire, cursor, width);
                envelope.payloadStart = cursor + width;
                envelope.envelopeEnd = cursor + (int) length;
                return envelope;
            }
            if ((first & 0x40) == 0 || (first & 0x18) != 0) {
                return null;
            }
            int width = (first & 3) + 1;
            int cursor = position + 1;
            if (cursor + cidWidth > wire.length) {
                return null;
            }
            byte[] destination = Arrays.copyOfRange(wire, cursor, cursor + cidWidth);
            cursor += cidWidth;
            if (cursor + width > wire.length) {
                return null;
            }
            Envelope envelope = new Envelope();
            envelope.level = LEVEL_A;
            envelope.destination = destination;
            envelope.source = new byte[0];
            envelope.token = new byte[0];
            envelope.phase = (first >>> 2) & 1;
            envelope.numberWidth = width;
            envelope.numberRaw = readNumber(wire, cursor, width);
            envelope.payloadStart = cursor + width;
            envelope.envelopeEnd = wire.length;
            return envelope;
        } catch (IndexOutOfBounds error) {
            return null;
        }
    }

    private static final class IndexOutOfBounds extends RuntimeException {}

    private static long readVarint(byte[] wire, int[] hold, int end) {
        int start = hold[0];
        if (start >= end) {
            throw new IndexOutOfBounds();
        }
        int first = wire[start] & 255;
        int width = 1 << (first >>> 6);
        if (start + width > end) {
            throw new IndexOutOfBounds();
        }
        long value = first & 0x3f;
        for (int i = 1; i < width; i++) {
            value = (value << 8) | (wire[start + i] & 255);
        }
        hold[0] = start + width;
        return value;
    }

    private static long readNumber(byte[] wire, int position, int width) {
        long value = 0;
        for (int i = 0; i < width; i++) {
            value = (value << 8) | (wire[position + i] & 255);
        }
        return value;
    }

    private static Long annotation(List<Long> auth, int attempt) {
        return attempt < auth.size() ? auth.get(attempt) : null;
    }

    private boolean inWindow(long generation) {
        if (generation == currentEpoch) {
            return true;
        }
        if (currentEpoch >= 1 && generation == currentEpoch - 1) {
            return true;
        }
        return generation == currentEpoch + 1 && generation <= AuditIo.MAX62;
    }

    private boolean epochOrderingViolated(long pn, long generation) {
        for (Map.Entry<Long, long[]> entry : epochs.entrySet()) {
            long epoch = entry.getKey();
            if (epoch == generation) {
                continue;
            }
            long[] bounds = entry.getValue();
            if (epoch > generation) {
                if (pn >= bounds[0]) {
                    return true;
                }
            } else if (pn <= bounds[1]) {
                return true;
            }
        }
        return false;
    }

    private void recordEpoch(long generation, long pn) {
        long[] bounds = epochs.get(generation);
        if (bounds == null) {
            epochs.put(generation, new long[] {pn, pn, 1});
            journal.push(() -> epochs.remove(generation));
        } else {
            long min = bounds[0];
            long max = bounds[1];
            long count = bounds[2];
            bounds[0] = Math.min(min, pn);
            bounds[1] = Math.max(max, pn);
            bounds[2] = count + 1;
            journal.push(
                    () -> {
                        bounds[0] = min;
                        bounds[1] = max;
                        bounds[2] = count;
                    });
        }
        if (generation == currentEpoch + 1) {
            long previous = currentEpoch;
            currentEpoch = generation;
            journal.push(() -> currentEpoch = previous);
        }
    }

    private void closeConnection(long code, long offset, int event, int packet) {
        if (connectionClosed) {
            return;
        }
        connectionClosed = true;
        closedRow = Main.object("event", event, "packet", packet, "offset", offset, "code", code);
    }

    // ------------------------------------------------------------------ frame evaluation

    /** Reads and applies frames; returns the close code and offset when a CLOSE frame ends it. */
    private long[] readFrames(byte[] wire, Envelope envelope, int destination, List<Frame> frames) {
        int end = envelope.envelopeEnd;
        if (envelope.payloadStart == end) {
            throw new Fail(FRAME_ENCODING_ERROR);
        }
        int position = envelope.payloadStart;
        while (position < end) {
            Frame frame = decodeFrame(wire, position, end, envelope.level);
            applyFrame(frame, envelope.level, destination);
            frames.add(frame);
            if (frame.type == 0x1c || frame.type == 0x1d) {
                return new long[] {frame.error, frame.start};
            }
            position = frame.end;
        }
        return null;
    }

    private Frame decodeFrame(byte[] wire, int start, int end, int level) {
        int type = wire[start] & 255;
        if ((type & 0xc0) != 0) {
            throw new Fail(FRAME_ENCODING_ERROR);
        }
        if (type >= 64 || (type >= 0x20 && type <= 0x1f)) {
            throw new Fail(FRAME_ENCODING_ERROR);
        }
        if (!supported(type)) {
            throw new Fail(FRAME_ENCODING_ERROR);
        }
        if (SERVER_ONLY[type]) {
            throw new Fail(PROTOCOL_VIOLATION);
        }
        if (!LONG_LEVEL[type] && level != LEVEL_A) {
            throw new Fail(PROTOCOL_VIOLATION);
        }
        Frame frame = new Frame();
        frame.type = type;
        frame.start = start;
        AuditIo.Cursor cursor = new AuditIo.Cursor(wire, start + 1, end);
        try {
            switch (type) {
                case 0x00:
                case 0x01:
                    frame.end = start + 1;
                    return frame;
                case 0x02:
                case 0x03:
                    {
                        frame.largest = cursor.v();
                        frame.delay = cursor.v();
                        long count = cursor.v();
                        frame.first = cursor.v();
                        if (frame.first > frame.largest) {
                            throw new Fail(FRAME_ENCODING_ERROR);
                        }
                        long extra = type == 0x03 ? 3 : 0;
                        long available = cursor.remaining() - extra;
                        if (count > available / 2) {
                            throw new Fail(FRAME_ENCODING_ERROR);
                        }
                        int total = (int) count;
                        long[][] pairs = new long[total][];
                        long[][] ranges = new long[total + 1][];
                        long low = frame.largest - frame.first;
                        ranges[total] = new long[] {low, frame.largest + 1};
                        for (int i = 0; i < total; i++) {
                            long gap = cursor.v();
                            long range = cursor.v();
                            if (gap > low || low - gap < 2) {
                                throw new Fail(FRAME_ENCODING_ERROR);
                            }
                            long high = low - gap - 2;
                            if (range > high) {
                                throw new Fail(FRAME_ENCODING_ERROR);
                            }
                            pairs[i] = new long[] {gap, range};
                            ranges[total - 1 - i] = new long[] {high - range, high + 1};
                            low = high - range;
                        }
                        frame.pairs = pairs;
                        frame.ranges = ranges;
                        if (type == 0x03) {
                            frame.ecn = new long[] {cursor.v(), cursor.v(), cursor.v()};
                        }
                        frame.end = cursor.position();
                        return frame;
                    }
                case 0x04:
                    frame.id = cursor.v();
                    frame.error = cursor.v();
                    frame.value = cursor.v();
                    frame.end = cursor.position();
                    return frame;
                case 0x05:
                    frame.id = cursor.v();
                    frame.error = cursor.v();
                    frame.end = cursor.position();
                    return frame;
                case 0x06:
                    frame.offset = cursor.v();
                    frame.length = cursor.v();
                    frame.data = cursor.bytes(frame.length);
                    frame.end = cursor.position();
                    return frame;
                case 0x08:
                case 0x09:
                case 0x0a:
                case 0x0b:
                case 0x0c:
                case 0x0d:
                case 0x0e:
                case 0x0f:
                    frame.hasOffset = (type & 4) != 0;
                    frame.hasLength = (type & 2) != 0;
                    frame.fin = (type & 1) != 0;
                    frame.id = cursor.v();
                    if (frame.hasOffset) {
                        frame.offset = cursor.v();
                    }
                    if (frame.hasLength) {
                        frame.length = cursor.v();
                        frame.data = cursor.bytes(frame.length);
                    } else {
                        frame.data = cursor.rest();
                        frame.length = frame.data.length;
                    }
                    frame.end = cursor.position();
                    return frame;
                case 0x10:
                case 0x12:
                case 0x13:
                case 0x14:
                case 0x16:
                case 0x17:
                    frame.maximum = cursor.v();
                    if ((type == 0x12 || type == 0x13 || type == 0x16 || type == 0x17)
                            && frame.maximum > (1L << 60)) {
                        throw new Fail(FRAME_ENCODING_ERROR);
                    }
                    frame.end = cursor.position();
                    return frame;
                case 0x11:
                case 0x15:
                    frame.id = cursor.v();
                    frame.maximum = cursor.v();
                    frame.end = cursor.position();
                    return frame;
                case 0x18:
                    frame.sequence = cursor.v();
                    frame.retirePriorTo = cursor.v();
                    int cidLength = cursor.u8();
                    if (cidLength < 1 || cidLength > 20) {
                        throw new Fail(FRAME_ENCODING_ERROR);
                    }
                    frame.data = cursor.bytes(cidLength);
                    frame.token = cursor.bytes(16);
                    if (frame.retirePriorTo > frame.sequence) {
                        throw new Fail(FRAME_ENCODING_ERROR);
                    }
                    frame.end = cursor.position();
                    return frame;
                case 0x19:
                    frame.sequence = cursor.v();
                    frame.end = cursor.position();
                    return frame;
                case 0x1a:
                case 0x1b:
                    frame.data = cursor.bytes(8);
                    frame.end = cursor.position();
                    return frame;
                case 0x1c:
                    frame.error = cursor.v();
                    frame.value = cursor.v();
                    frame.length = cursor.v();
                    frame.data = cursor.bytes(frame.length);
                    frame.end = cursor.position();
                    return frame;
                case 0x1d:
                    frame.error = cursor.v();
                    frame.length = cursor.v();
                    frame.data = cursor.bytes(frame.length);
                    frame.end = cursor.position();
                    return frame;
                case 0x30:
                    frame.data = cursor.rest();
                    frame.end = end;
                    return frame;
                case 0x31:
                    frame.length = cursor.v();
                    frame.data = cursor.bytes(frame.length);
                    frame.end = cursor.position();
                    return frame;
                default:
                    throw new Fail(FRAME_ENCODING_ERROR);
            }
        } catch (AuditIo.Truncated truncated) {
            throw new Fail(FRAME_ENCODING_ERROR);
        }
    }

    private static boolean supported(int type) {
        if (type >= 0x20 && type <= 0x1f) {
            return false;
        }
        if (type >= 0x08 && type <= 0x0f) {
            return true;
        }
        switch (type) {
            case 0x00:
            case 0x01:
            case 0x02:
            case 0x03:
            case 0x04:
            case 0x05:
            case 0x06:
            case 0x07:
            case 0x10:
            case 0x11:
            case 0x12:
            case 0x13:
            case 0x14:
            case 0x15:
            case 0x16:
            case 0x17:
            case 0x18:
            case 0x19:
            case 0x1a:
            case 0x1b:
            case 0x1c:
            case 0x1d:
            case 0x1e:
            case 0x30:
            case 0x31:
                return true;
            default:
                return false;
        }
    }

    private void applyFrame(Frame frame, int level, int destination) {
        switch (frame.type) {
            case 0x02:
            case 0x03:
                {
                    LevelState state = levels[level];
                    state.acknowledged.addAll(frame.ranges, journal);
                    if (frame.type == 0x03) {
                        for (int i = 0; i < 3; i++) {
                            if (frame.ecn[i] > state.ecn[i]) {
                                long previous = state.ecn[i];
                                state.ecn[i] = frame.ecn[i];
                                final int index = i;
                                journal.push(() -> state.ecn[index] = previous);
                            }
                        }
                    }
                    return;
                }
            case 0x04:
                resetStream(frame);
                return;
            case 0x05:
                stopSending(frame);
                return;
            case 0x06:
                {
                    if (frame.offset > AuditIo.MAX62 - frame.length) {
                        throw new Fail(FRAME_ENCODING_ERROR);
                    }
                    AuditIo.Ledger ledger = levels[level].crypto;
                    if (!ledger.add(frame.offset, frame.data, journal)) {
                        throw new Fail(PROTOCOL_VIOLATION);
                    }
                    return;
                }
            case 0x10:
                if (frame.maximum > sendMaxData) {
                    long previous = sendMaxData;
                    sendMaxData = frame.maximum;
                    journal.push(() -> sendMaxData = previous);
                }
                return;
            case 0x11:
                {
                    Stream stream = reference(frame.id, true);
                    if (frame.maximum > stream.sendMax) {
                        long previous = stream.sendMax;
                        stream.sendMax = frame.maximum;
                        journal.push(() -> stream.sendMax = previous);
                    }
                    return;
                }
            case 0x12:
            case 0x13:
                {
                    boolean bidi = frame.type == 0x12;
                    long current = bidi ? sendMaxStreamsBidi : sendMaxStreamsUni;
                    if (frame.maximum > current) {
                        if (bidi) {
                            sendMaxStreamsBidi = frame.maximum;
                            journal.push(() -> sendMaxStreamsBidi = current);
                        } else {
                            sendMaxStreamsUni = frame.maximum;
                            journal.push(() -> sendMaxStreamsUni = current);
                        }
                    }
                    return;
                }
            case 0x15:
                reference(frame.id, false);
                return;
            case 0x18:
                newConnectionId(frame);
                return;
            case 0x19:
                retireConnectionId(frame, destination);
                return;
            default:
                return;
        }
    }

    // ------------------------------------------------------------------ streams

    /**
     * Resolves a stream reference, enforcing direction, open state and client stream limits, and
     * implicitly opening all lower client identifiers of the same category.
     */
    private Stream reference(long id, boolean sendReference) {
        int category = (int) (id & 3);
        long index = id >>> 2;
        if (sendReference) {
            if (category == 2) {
                throw new Fail(STREAM_STATE_ERROR);
            }
            if (category == 1 || category == 3) {
                if (index >= (category == 1 ? localBidi : localUni)) {
                    throw new Fail(STREAM_STATE_ERROR);
                }
            } else {
                if (index >= limitBidi) {
                    throw new Fail(STREAM_LIMIT_ERROR);
                }
                openClientStream(id);
            }
        } else {
            if (category == 3) {
                throw new Fail(STREAM_STATE_ERROR);
            }
            if (category == 1) {
                if (index >= localBidi) {
                    throw new Fail(STREAM_STATE_ERROR);
                }
            } else {
                if (index >= (category == 0 ? limitBidi : limitUni)) {
                    throw new Fail(STREAM_LIMIT_ERROR);
                }
                openClientStream(id);
            }
        }
        Stream stream = streams.get(id);
        if (stream == null) {
            stream = new Stream(id);
            streams.put(id, stream);
            journal.push(() -> streams.remove(id));
        }
        return stream;
    }

    private void openClientStream(long id) {
        int category = (int) (id & 3);
        long index = (id >>> 2) + 1;
        if (category == 0) {
            if (index > openedBidi) {
                long previous = openedBidi;
                openedBidi = index;
                journal.push(() -> openedBidi = previous);
            }
        } else {
            if (index > openedUni) {
                long previous = openedUni;
                openedUni = index;
                journal.push(() -> openedUni = previous);
            }
        }
    }

    private void setHigh(Stream stream, long value) {
        if (value != stream.high) {
            long previous = stream.high;
            long delta = value - previous;
            stream.high = value;
            used += delta;
            journal.push(
                    () -> {
                        stream.high = previous;
                        used -= delta;
                    });
        }
    }

    private void checkFlowControl(Stream stream, long candidate) {
        if (candidate > limitStream) {
            throw new Fail(FLOW_CONTROL_ERROR);
        }
        if (used - stream.high + candidate > limitConnection) {
            throw new Fail(FLOW_CONTROL_ERROR);
        }
        setHigh(stream, candidate);
    }

    private void streamFrame(Frame frame) {
        Stream stream = reference(frame.id, false);
        long end = frame.offset + frame.length;
        if (end > AuditIo.MAX62) {
            throw new Fail(FRAME_ENCODING_ERROR);
        }
        if (stream.finalSize != null) {
            if (end > stream.finalSize) {
                throw new Fail(FINAL_SIZE_ERROR);
            }
            if (frame.fin && end != stream.finalSize) {
                throw new Fail(FINAL_SIZE_ERROR);
            }
        } else if (frame.fin && end < stream.high) {
            throw new Fail(FINAL_SIZE_ERROR);
        }
        checkFlowControl(stream, Math.max(stream.high, end));
        if (frame.fin && stream.finalSize == null) {
            stream.finalSize = end;
            final long size = end;
            journal.push(() -> stream.finalSize = null);
        }
        if (stream.reset == null && !stream.bytes.add(frame.offset, frame.data, journal)) {
            throw new Fail(PROTOCOL_VIOLATION);
        }
    }

    private void resetStream(Frame frame) {
        Stream stream = reference(frame.id, false);
        long size = frame.value;
        if (size < stream.high) {
            throw new Fail(FINAL_SIZE_ERROR);
        }
        if (stream.finalSize != null && stream.finalSize != size) {
            throw new Fail(FINAL_SIZE_ERROR);
        }
        checkFlowControl(stream, size);
        if (stream.finalSize == null) {
            stream.finalSize = size;
            journal.push(() -> stream.finalSize = null);
        }
        if (stream.reset == null) {
            stream.reset = frame.error;
            final long code = frame.error;
            journal.push(() -> stream.reset = null);
        }
    }

    private void stopSending(Frame frame) {
        Stream stream = reference(frame.id, true);
        if (stream.stop == null) {
            stream.stop = frame.error;
            final long code = frame.error;
            journal.push(() -> stream.stop = null);
        }
    }

    // ------------------------------------------------------------------ connection identifiers

    private void newConnectionId(Frame frame) {
        byte[][] observed = peerObserved.get(frame.sequence);
        if (observed != null
                && (!Arrays.equals(observed[0], frame.data) || !Arrays.equals(observed[1], frame.token))) {
            throw new Fail(PROTOCOL_VIOLATION);
        }
        Long owner = peerOwner.get(new AuditIo.ByteKey(frame.data));
        if (owner != null && owner != frame.sequence) {
            throw new Fail(PROTOCOL_VIOLATION);
        }
        if (observed == null) {
            peerObserved.put(frame.sequence, new byte[][] {frame.data, frame.token});
            journal.push(() -> peerObserved.remove(frame.sequence));
        }
        if (owner == null) {
            AuditIo.ByteKey key = new AuditIo.ByteKey(frame.data);
            peerOwner.put(key, frame.sequence);
            journal.push(() -> peerOwner.remove(key));
        }
        long threshold = Math.max(retirePriorTo, frame.retirePriorTo);
        if (threshold != retirePriorTo) {
            long previous = retirePriorTo;
            retirePriorTo = threshold;
            journal.push(() -> retirePriorTo = previous);
            Iterator<Long> active = peerActive.iterator();
            while (active.hasNext()) {
                long sequence = active.next();
                if (sequence >= threshold) {
                    break;
                }
                active.remove();
                journal.push(() -> peerActive.add(sequence));
            }
        }
        if (frame.sequence >= retirePriorTo && peerActive.add(frame.sequence)) {
            journal.push(() -> peerActive.remove(frame.sequence));
        }
        if (peerActive.size() > cidLimit) {
            throw new Fail(CONNECTION_ID_LIMIT_ERROR);
        }
    }

    private void retireConnectionId(Frame frame, int destination) {
        if (frame.sequence >= localCids.length) {
            throw new Fail(PROTOCOL_VIOLATION);
        }
        if (frame.sequence == destination) {
            throw new Fail(PROTOCOL_VIOLATION);
        }
        if (retiredLocal.add(frame.sequence)) {
            journal.push(() -> retiredLocal.remove(frame.sequence));
        }
    }

    // ------------------------------------------------------------------ canonical envelopes

    private byte[] canonicalize(List<Frame> frames) {
        AuditIo.ByteOut out = new AuditIo.ByteOut();
        for (Frame frame : frames) {
            frame.write(out);
        }
        return out.toArray();
    }

    private byte[] canonicalEnvelope(Envelope envelope, long pn, long expected, byte[] payload) {
        int width = AuditIo.canonicalWidth(pn, expected);
        AuditIo.ByteOut out = new AuditIo.ByteOut();
        if (envelope.level == LEVEL_A) {
            out.u8(0x40 | (envelope.phase << 2) | (width - 1));
            out.bytes(envelope.destination);
            out.pn(pn, width);
            out.bytes(payload);
            return out.toArray();
        }
        out.u8((envelope.level == LEVEL_I ? 0xc0 : 0xe0) | (width - 1));
        out.u8(0);
        out.u8(0);
        out.u8(1);
        out.u8(envelope.destination.length);
        out.bytes(envelope.destination);
        out.u8(envelope.source.length);
        out.bytes(envelope.source);
        if (envelope.level == LEVEL_I) {
            out.v(envelope.token.length);
            out.bytes(envelope.token);
        }
        out.v(width + payload.length);
        out.pn(pn, width);
        out.bytes(payload);
        return out.toArray();
    }

    // ------------------------------------------------------------------ reporting

    private Map<String, Object> report(List<Object> packets, List<Object> datagrams) {
        Map<String, Object> out = new LinkedHashMap<>();
        out.put("packets", packets);
        out.put("datagrams", datagrams);
        out.put("closed", closedRow);
        List<Object> keys = new ArrayList<>();
        if ((keysMask & 1) != 0) {
            keys.add("I");
        }
        if ((keysMask & 2) != 0) {
            keys.add("H");
        }
        if ((keysMask & 4) != 0) {
            keys.add("A");
        }
        out.put("keys", keys);
        Map<String, Object> received = new LinkedHashMap<>();
        for (int level = 0; level < 3; level++) {
            received.put(
                    LEVEL_NAMES[level], levels[level].largest < 0 ? null : levels[level].largest);
        }
        out.put("received", received);
        out.put("key_epoch", currentEpoch);
        List<Object> epochRows = new ArrayList<>();
        for (Map.Entry<Long, long[]> entry : epochs.entrySet()) {
            epochRows.add(
                    Main.object(
                            "epoch",
                            entry.getKey(),
                            "min",
                            entry.getValue()[0],
                            "max",
                            entry.getValue()[1],
                            "count",
                            entry.getValue()[2]));
        }
        out.put("epochs", epochRows);
        Map<String, Object> opened = new LinkedHashMap<>();
        opened.put("bidi", openedBidi);
        opened.put("uni", openedUni);
        out.put("opened", opened);
        out.put("used", used);
        out.put("send_max_data", sendMaxData);
        Map<String, Object> sendMaxStreams = new LinkedHashMap<>();
        sendMaxStreams.put("bidi", sendMaxStreamsBidi);
        sendMaxStreams.put("uni", sendMaxStreamsUni);
        out.put("send_max_streams", sendMaxStreams);

        List<Object> streamRows = new ArrayList<>();
        for (Stream stream : streams.values()) {
            long prefix = stream.bytes.prefixLength();
            streamRows.add(
                    Main.object(
                            "id",
                            stream.id,
                            "high",
                            stream.high,
                            "final",
                            stream.finalSize,
                            "reset",
                            stream.reset,
                            "stop",
                            stream.stop,
                            "send_max",
                            stream.sendMax,
                            "ranges",
                            intervals(stream.bytes.segments()),
                            "unique",
                            stream.bytes.unique(),
                            "prefix",
                            prefix,
                            "sha256",
                            AuditIo.hex(
                                    AuditIo.sha256().digest(stream.bytes.prefixBytes(prefix)))));
        }
        out.put("streams", streamRows);

        List<Object> cryptoRows = new ArrayList<>();
        for (int level = 0; level < 3; level++) {
            AuditIo.Ledger ledger = levels[level].crypto;
            long prefix = ledger.prefixLength();
            cryptoRows.add(
                    Main.object(
                            "level",
                            LEVEL_NAMES[level],
                            "ranges",
                            intervals(ledger.segments()),
                            "unique",
                            ledger.unique(),
                            "prefix",
                            prefix,
                            "sha256",
                            AuditIo.hex(AuditIo.sha256().digest(ledger.prefixBytes(prefix)))));
        }
        out.put("crypto", cryptoRows);

        List<Object> acknowledgedRows = new ArrayList<>();
        for (int level = 0; level < 3; level++) {
            AuditIo.Ranges ranges = levels[level].acknowledged;
            MessageDigest digest = AuditIo.sha256();
            for (long[] interval : ranges.intervals()) {
                digest.update(be64(interval[0]));
                digest.update(be64(interval[1]));
            }
            List<Object> ecn = new ArrayList<>(3);
            ecn.add(levels[level].ecn[0]);
            ecn.add(levels[level].ecn[1]);
            ecn.add(levels[level].ecn[2]);
            acknowledgedRows.add(
                    Main.object(
                            "level",
                            LEVEL_NAMES[level],
                            "count",
                            ranges.cardinality(),
                            "intervals",
                            ranges.size(),
                            "prefix",
                            ranges.prefix(),
                            "sha256",
                            AuditIo.hex(digest.digest()),
                            "ecn",
                            ecn));
        }
        out.put("acknowledged", acknowledgedRows);

        List<Object> peerRows = new ArrayList<>();
        for (Map.Entry<Long, byte[][]> entry : peerObserved.entrySet()) {
            if (peerActive.contains(entry.getKey())) {
                peerRows.add(
                        Main.object(
                                "sequence",
                                entry.getKey(),
                                "id",
                                AuditIo.hex(entry.getValue()[0]),
                                "token",
                                AuditIo.hex(entry.getValue()[1])));
        }
        }
        out.put("peer_cids", peerRows);
        out.put("retire_prior_to", retirePriorTo);
        out.put("retired_local", pointIntervals(retiredLocal));
        return out;
    }

    private static List<Object> intervals(ArrayList<AuditIo.Segment> segments) {
        List<Object> out = new ArrayList<>(segments.size());
        for (AuditIo.Segment segment : segments) {
            List<Object> range = new ArrayList<>(2);
            range.add(segment.start);
            range.add(segment.end);
            out.add(range);
        }
        return out;
    }

    private static List<Object> pointIntervals(TreeSet<Long> points) {
        List<Object> out = new ArrayList<>();
        Long start = null;
        long previous = 0;
        for (long value : points) {
            if (start == null) {
                start = value;
            } else if (value != previous + 1) {
                List<Object> range = new ArrayList<>(2);
                range.add(start);
                range.add(previous + 1);
                out.add(range);
                start = value;
            }
            previous = value;
        }
        if (start != null) {
            List<Object> range = new ArrayList<>(2);
            range.add(start);
            range.add(previous + 1);
            out.add(range);
        }
        return out;
    }

    private static byte[] be64(long value) {
        byte[] out = new byte[8];
        for (int i = 7; i >= 0; i--) {
            out[i] = (byte) (value >>> (8 * i));
        }
        return out;
    }
